"use client";

import { memo, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { CategoryChip } from "./parts/category-chip";
import { resolveLocale } from "./lib/resolve-locale";
import {
  defaultCategoryCloudLabels,
  type CategoryCloudItem,
  type CategoryCloudLabels,
  type CategoryCloudProps,
  type NormalizedItem,
} from "./types";

/** Merge `labels` over the defaults — an `undefined` key never erases a default (C2). */
function resolveLabels(labels: CategoryCloudLabels | undefined): Required<CategoryCloudLabels> {
  return {
    group: labels?.group ?? defaultCategoryCloudLabels.group,
    count: labels?.count ?? defaultCategoryCloudLabels.count,
  };
}

const normalizeItems = (
  items: CategoryCloudItem[] | string[],
): NormalizedItem[] => {
  const seen = new Map<string, number>();
  return items.map((entry) => {
    const raw =
      typeof entry === "string"
        ? { value: entry, label: entry, count: undefined }
        : { value: entry.value, label: entry.label ?? entry.value, count: entry.count };
    const n = seen.get(raw.value) ?? 0;
    seen.set(raw.value, n + 1);
    // NUL separator: no real `value` contains it, so a repeat's key cannot collide with another value.
    return { ...raw, key: n === 0 ? raw.value : `${raw.value}\u0000${n}` };
  });
};

/**
 * CategoryCloud — always-visible flex-wrap of clickable category chips
 * with optional counts. Single-select, controlled-or-uncontrolled.
 *
 * Pass `string[]` as shorthand for items without counts:
 *   <CategoryCloud items={["All", "Tech", "Design"]} />
 *
 * Or full form for counts + display labels:
 *   <CategoryCloud items={[{ value: "tech", label: "Technology", count: 12 }]} />
 */
function CategoryCloudImpl(props: CategoryCloudProps) {
  const {
    items,
    value: controlledValue,
    defaultValue = null,
    onChange,
    toggleable = true,
    title,
    headingAs = "h3",
    formatCount,
    ariaLabel,
    labels: labelsProp,
    locale: localeProp,
    getHref,
    linkComponent,
    className,
    titleClassName,
  } = props;

  const [internalValue, setInternalValue] = useState<string | null>(defaultValue);
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : internalValue;

  const normalized = useMemo(() => normalizeItems(items), [items]);

  const labels = useMemo(() => resolveLabels(labelsProp), [labelsProp]);
  const locale = useMemo(() => resolveLocale(localeProp), [localeProp]);
  const numberFormat = useMemo(() => new Intl.NumberFormat(locale), [locale]);

  // Dev-only: a controlled `value` that matches no item, and repeated `item.value`s — once per change
  // of the problem (an inline `items` array re-renders with the same content and must not re-warn).
  const lastWarning = useRef("");
  useEffect(() => {
    if (process.env.NODE_ENV === "production") return;
    const values = normalized.map((n) => n.value);
    const dups = [...new Set(values.filter((v, i) => values.indexOf(v) !== i))];
    const warnings: string[] = [];
    if (dups.length > 0) {
      warnings.push(
        `[CategoryCloud] Duplicate item values: ${dups.join(", ")}. Each value should be unique; repeated chips all read as active together.`,
      );
    }
    if (isControlled && controlledValue != null && !values.includes(controlledValue)) {
      warnings.push(
        `[CategoryCloud] Controlled value "${controlledValue}" matches no item, so no chip is active.`,
      );
    }
    const key = warnings.join("\n");
    if (key === lastWarning.current) return;
    lastWarning.current = key;
    for (const warning of warnings) console.warn(warning);
  }, [normalized, isControlled, controlledValue]);

  const handleClick = useCallback(
    (next: string, linkChip: boolean) => {
      const resolved =
        !linkChip && toggleable && value === next ? null : next;
      if (!isControlled) setInternalValue(resolved);
      onChange?.(resolved);
    },
    [isControlled, onChange, toggleable, value],
  );

  const HeadingTag = headingAs;
  const groupLabel = ariaLabel ?? title ?? labels.group;

  return (
    <div className={className}>
      {title ? (
        <HeadingTag
          className={cn(
            "mb-4 border-b border-border pb-2 font-serif text-lg font-bold text-foreground",
            titleClassName,
          )}
        >
          {title}
        </HeadingTag>
      ) : null}
      <div
        role="group"
        aria-label={groupLabel}
        className="flex flex-wrap gap-2"
      >
        {normalized.map((item) => {
          const href = getHref?.({ value: item.value, label: item.label, count: item.count });
          const countLabel =
            item.count === undefined
              ? ""
              : formatCount
                ? formatCount(item.count)
                : labels.count(item.count, numberFormat.format(item.count === 0 ? 0 : item.count));
          return (
            <CategoryChip
              key={item.key}
              item={item}
              isActive={value === item.value}
              countLabel={countLabel}
              href={href}
              linkComponent={linkComponent}
              onClick={() => handleClick(item.value, typeof href === "string")}
            />
          );
        })}
      </div>
    </div>
  );
}

export const CategoryCloud = memo(CategoryCloudImpl);
CategoryCloud.displayName = "CategoryCloud";

export default CategoryCloud;

export { CategoryCloud, default } from "./category-cloud";
export { defaultCategoryCloudLabels } from "./types";
export type {
  CategoryCloudHeadingLevel,
  CategoryCloudItem,
  CategoryCloudLabels,
  CategoryCloudProps,
} from "./types";

// @ilinxa/category-cloud 0.3.0

import type { ElementType } from "react";

export type CategoryCloudHeadingLevel = "h2" | "h3" | "h4";

/** User-facing strings. Every key is optional; an `undefined` key keeps the default. */
export interface CategoryCloudLabels {
  /** Accessible name of the chip group when neither `ariaLabel` nor `title` is given. Default: "Categories". */
  group?: string;
  /**
   * Text appended to a chip label when it has a `count`. Receives the raw number and the
   * `locale`-formatted one. Default: `" (12)"`. `formatCount` overrides this entirely.
   */
  count?: (count: number, formatted: string) => string;
}

/** Default English labels — exported for consumer composition. */
export const defaultCategoryCloudLabels: Required<CategoryCloudLabels> = {
  group: "Categories",
  count: (_count, formatted) => ` (${formatted})`,
};

export interface CategoryCloudItem {
  /** Stable identifier, used as the selection value. */
  value: string;
  /** Display text. Defaults to `value` if not provided. */
  label?: string;
  /** Optional count rendered after the label. */
  count?: number;
}

export interface CategoryCloudProps {
  /** Categories to render. Pass `string[]` as shorthand for `[{value,label}]`. */
  items: CategoryCloudItem[] | string[];

  /** Controlled selection value. Pass null to clear. */
  value?: string | null;
  /** Uncontrolled initial selection. Default: null. */
  defaultValue?: string | null;
  /** Selection change callback. Fires with null when re-clicking active (if toggleable). */
  onChange?: (value: string | null) => void;

  /** Whether re-clicking the active chip clears the selection. Default: true. */
  toggleable?: boolean;

  /** Optional title rendered above the cloud. */
  title?: string;
  /** Heading semantic level. Default: 'h3'. */
  headingAs?: CategoryCloudHeadingLevel;

  /**
   * Full override of the count text (including the leading space / parentheses). Wins over
   * `labels.count` and receives the raw number, so format it yourself.
   */
  formatCount?: (count: number) => string;

  /** ARIA group label. Precedence: `ariaLabel` > `title` > `labels.group`. */
  ariaLabel?: string;

  /** User-facing strings (group name, count text). Partial; `undefined` keys keep the defaults. */
  labels?: CategoryCloudLabels;
  /** BCP 47 locale used to format counts (`Intl.NumberFormat`). Default `"en"`; an invalid tag falls back to `"en"`. */
  locale?: string;

  /**
   * Link mode: return a URL for an item and its chip renders as a link (`linkComponent`) instead of a
   * button — no `aria-pressed`, `aria-current="page"` on the chip matching `value`. `onChange` still fires
   * on click (default is not prevented) so a router can react. An item for which this returns
   * `undefined` stays a button. `toggleable` has no meaning for link chips.
   */
  getHref?: (item: CategoryCloudItem) => string | undefined;
  /** Element type rendered for link chips (e.g. a router's `Link`). Default `"a"`. Rendered as an element type, never `asChild`. */
  linkComponent?: ElementType;

  /** Override classes for the root container. */
  className?: string;
  /** Override classes for the title heading. */
  titleClassName?: string;
}

/** Internal normalized item shape — both `string[]` and `CategoryCloudItem[]` flatten to this. */
export interface NormalizedItem {
  value: string;
  label: string;
  count: number | undefined;
  /** React key — `value`, suffixed only for a repeated `value` so duplicates do not collide. */
  key: string;
}

import type { ElementType, MouseEvent } from "react";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import type { NormalizedItem } from "../types";

const chipClass =
  "rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2";

/**
 * One chip in the cloud. A native `<button>` (toggle) by default, or — when `href` is given — the
 * `linkComponent` element type (default `<a>`) with `aria-current="page"` on the active chip. A `<Badge>`
 * inside carries the visual.
 */
export function CategoryChip({
  item,
  isActive,
  countLabel,
  onClick,
  href,
  linkComponent,
}: {
  item: NormalizedItem;
  isActive: boolean;
  countLabel: string;
  onClick: () => void;
  href?: string;
  linkComponent?: ElementType;
}) {
  const badge = (
    <Badge
      variant={isActive ? "default" : "secondary"}
      className={cn("cursor-pointer", isActive ? "" : "hover:bg-secondary/80")}
    >
      {item.label}
      {countLabel}
    </Badge>
  );

  if (typeof href === "string") {
    const Link: ElementType = linkComponent ?? "a";
    return (
      <Link
        href={href}
        aria-current={isActive ? "page" : undefined}
        onClick={(event: MouseEvent) => {
          // Ctrl / Cmd / Shift / Alt open the link elsewhere: the current page does not change.
          if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0) return;
          onClick();
        }}
        className={chipClass}
      >
        {badge}
      </Link>
    );
  }

  return (
    <button type="button" aria-pressed={isActive} onClick={onClick} className={chipClass}>
      {badge}
    </button>
  );
}

/**
 * A valid BCP 47 tag for `locale`, else `"en"`. An invalid tag (`"en_US"` from an i18n library)
 * makes `Intl.NumberFormat` throw — that must not take down the render.
 */
export function resolveLocale(locale: string | undefined): string {
  if (!locale) return "en";
  try {
    return Intl.getCanonicalLocales(locale)[0] ?? "en";
  } catch {
    return "en";
  }
}
